using GarageManager.BUS;using GarageManager.DTO;using System.Data;
namespace GarageManager.GUI;
public sealed class MainForm:Form
{
 readonly GarageService svc=new();readonly TabControl tabs=new(){Dock=DockStyle.Fill};readonly DataGridView customers=Grid(),cars=Grid(),parts=Grid(),cartGrid=Grid(),orders=Grid(),reportOrders=Grid();readonly TextBox customerName=new(){Width=180},phone=new(){Width=130},address=new(){Width=210},plate=new(){Width=120},make=new(){Width=120},year=new(){Width=80},partName=new(){Width=210},partPrice=new(){Width=100},partStock=new(){Width=70},repairDescription=new(){Width=300};readonly ComboBox carOwner=new(){Width=170,DropDownStyle=ComboBoxStyle.DropDownList},repairCar=new(){Width=180,DropDownStyle=ComboBoxStyle.DropDownList},partChoice=new(){Width=190,DropDownStyle=ComboBoxStyle.DropDownList};readonly NumericUpDown qty=new(){Minimum=1,Maximum=999,Value=1,Width=70};readonly TextBox labor=new(){Width=100,Text="0"};readonly List<RepairLine> cart=new();int? customerId,partId;DataTable? ownerTable,partTable;
 public MainForm(){Text="AutoCare | Quản lý Garage & sửa chữa";Width=1320;Height=850;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(246,248,250);BuildHome();BuildOwnersCars();BuildParts();BuildRepairs();BuildReports();Controls.Add(tabs);Shown+=(_,_)=>RefreshAll();}
 static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,BackgroundColor=Color.White,BorderStyle=BorderStyle.None};TabPage Page(string s){var p=new TabPage(s){Padding=new Padding(10),BackColor=Color.FromArgb(246,248,250)};tabs.TabPages.Add(p);return p;}static Label L(string s)=>new(){Text=s,AutoSize=true,Margin=new Padding(5,9,1,2)};static Button B(string s,EventHandler e){var b=new Button{Text=s,AutoSize=true,Height=32,Margin=new Padding(3),BackColor=Color.White};b.Click+=e;return b;}static FlowLayoutPanel Bar(int h)=>new(){Dock=DockStyle.Top,Height=h,Padding=new Padding(2,5,2,4),WrapContents=true};
 void BuildHome(){var p=Page("Tổng quan");p.Controls.Add(new Label{Text="AUTOCARE  |  GARAGE MANAGEMENT",Font=new Font("Segoe UI",24,FontStyle.Bold),ForeColor=Color.FromArgb(30,64,114),AutoSize=true,Location=new Point(26,28)});p.Controls.Add(new Label{Text="Tiếp nhận xe • Quản lý phụ tùng • Phiếu sửa chữa • Thanh toán",Font=new Font("Segoe UI",13),AutoSize=true,Location=new Point(30,84)});var box=new Panel{Location=new Point(30,140),Size=new Size(560,180),BackColor=Color.White};box.Controls.Add(new Label{Text="Kết nối SQL Server",Font=new Font("Segoe UI",16,FontStyle.Bold),Location=new Point(18,18),AutoSize=true});box.Controls.Add(new Label{Text=@"Server: localhost\SQLEXPRESS  |  Database: GarageDB",Location=new Point(18,58),AutoSize=true});box.Controls.Add(new Label{Text="DTO → DAL → BUS → WinForms GUI  •  SqlTransaction",Location=new Point(18,94),AutoSize=true});var s=new Label{Name="stats",Location=new Point(18,128),AutoSize=true};box.Controls.Add(s);p.Controls.Add(box);}
 void BuildOwnersCars(){var p=Page("Chủ xe & tiếp nhận");var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=290};var ownerTop=Bar(74);ownerTop.Controls.AddRange(new Control[]{L("Họ tên"),customerName,L("Điện thoại"),phone,L("Địa chỉ"),address,B("Lưu chủ xe",(_,_)=>SaveCustomer()),B("Làm mới",(_,_)=>LoadCustomers())});split.Panel1.Controls.Add(customers);split.Panel1.Controls.Add(ownerTop);var carTop=Bar(74);carTop.Controls.AddRange(new Control[]{L("Biển số"),plate,L("Chủ xe"),carOwner,L("Hiệu xe"),make,L("Năm SX"),year,B("Lưu xe",(_,_)=>SaveCar()),B("Tra cứu biển số",(_,_)=>SearchCar())});split.Panel2.Controls.Add(cars);split.Panel2.Controls.Add(carTop);p.Controls.Add(split);customers.SelectionChanged+=(_,_)=>SelectCustomer();cars.SelectionChanged+=(_,_)=>SelectCar();}
 void BuildParts(){var p=Page("Kho phụ tùng");var top=Bar(78);top.Controls.AddRange(new Control[]{L("Tên phụ tùng"),partName,L("Đơn giá"),partPrice,L("Tồn kho"),partStock,B("Thêm / cập nhật",(_,_)=>SavePart()),B("Xóa",(_,_)=>DeletePart()),B("Làm mới",(_,_)=>LoadParts())});p.Controls.Add(parts);p.Controls.Add(top);parts.SelectionChanged+=(_,_)=>SelectPart();}
 void BuildRepairs(){var p=Page("Phiếu sửa chữa");var top=Bar(120);top.Controls.AddRange(new Control[]{L("Xe"),repairCar,L("Nội dung sửa"),repairDescription,L("Phụ tùng"),partChoice,L("SL"),qty,L("Tiền công"),labor,B("Thêm phụ tùng",(_,_)=>AddLine()),B("Lập phiếu (giao dịch)",(_,_)=>CreateRepair()),B("Xóa dòng",(_,_)=>RemoveLine())});var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=220};split.Panel1.Controls.Add(cartGrid);split.Panel2.Controls.Add(orders);p.Controls.Add(split);p.Controls.Add(top);}
 void BuildReports(){var p=Page("Báo cáo & thanh toán");var top=Bar(54);top.Controls.Add(new Label{Name="report",AutoSize=true,Font=new Font("Segoe UI",14,FontStyle.Bold),ForeColor=Color.DarkGreen,Margin=new Padding(8,8,16,2)});top.Controls.Add(B("Cập nhật",(_,_)=>LoadOrders()));top.Controls.Add(B("Thanh toán phiếu được chọn",(_,_)=>PaySelected()));p.Controls.Add(reportOrders);p.Controls.Add(top);}
 void RefreshAll(){try{ownerTable=svc.Repository.Customers();partTable=svc.Repository.Parts();LoadCustomers();LoadCars();LoadParts();LoadLookups();LoadOrders();var s=Controls.Find("stats",true).FirstOrDefault() as Label;if(s!=null)s.Text=$"{svc.Repository.Scalar("SELECT COUNT(*) FROM Xe")} xe tiếp nhận   •   {svc.Repository.Scalar("SELECT COUNT(*) FROM PhuTung")} loại phụ tùng   •   {svc.Repository.Scalar("SELECT COUNT(*) FROM PhieuSuaChua")} phiếu sửa chữa";}catch(Exception ex){Error(ex);}}
 void LoadCustomers(){ownerTable=svc.Repository.Customers();customers.DataSource=ownerTable;}
 void LoadCars(){cars.DataSource=svc.Repository.Vehicles();}
 void LoadParts(){partTable=svc.Repository.Parts();parts.DataSource=partTable;LoadLookups();}
 void LoadLookups(){ownerTable??=svc.Repository.Customers();carOwner.DataSource=ownerTable.Copy();carOwner.DisplayMember="TenKH";carOwner.ValueMember="MaKH";repairCar.DataSource=svc.Repository.Vehicles();repairCar.DisplayMember="BienSo";repairCar.ValueMember="BienSo";partTable??=svc.Repository.Parts();partChoice.DataSource=partTable.Copy();partChoice.DisplayMember="TenPhuTung";partChoice.ValueMember="MaPhuTung";}
 void SelectCustomer(){if(customers.CurrentRow?.DataBoundItem is not DataRowView r)return;customerId=Convert.ToInt32(r["MaKH"]);customerName.Text=r["TenKH"].ToString();phone.Text=r["DienThoai"].ToString();address.Text=r["DiaChi"].ToString();}
 void SaveCustomer(){try{svc.ValidateCustomer(customerName.Text,phone.Text);svc.Repository.SaveCustomer(customerId,customerName.Text.Trim(),phone.Text.Trim(),address.Text.Trim());LoadCustomers();LoadLookups();MessageBox.Show("Đã lưu thông tin chủ xe.");}catch(Exception ex){Error(ex);}}
 void SelectCar(){if(cars.CurrentRow?.DataBoundItem is not DataRowView r)return;plate.Text=r["BienSo"].ToString();make.Text=r["HieuXe"].ToString();year.Text=r["NamSanXuat"]==DBNull.Value?"":r["NamSanXuat"].ToString();carOwner.SelectedValue=Convert.ToInt32(r["MaKH"]);}
 void SaveCar(){try{svc.ValidateVehicle(plate.Text,make.Text);if(carOwner.SelectedValue is null)throw new InvalidOperationException("Chọn chủ xe.");int? y=int.TryParse(year.Text,out int v)?v:null;svc.Repository.SaveVehicle(plate.Text.Trim().ToUpperInvariant(),Convert.ToInt32(carOwner.SelectedValue),make.Text.Trim(),y);LoadCars();LoadLookups();MessageBox.Show("Đã lưu thông tin xe.");}catch(Exception ex){Error(ex);}}
 void SearchCar(){var term=plate.Text.Trim();if(string.IsNullOrWhiteSpace(term)){LoadCars();return;}try{cars.DataSource=svc.Repository.SearchVehicles(term);}catch(Exception ex){Error(ex);}}
 void SelectPart(){if(parts.CurrentRow?.DataBoundItem is not DataRowView r)return;partId=Convert.ToInt32(r["MaPhuTung"]);partName.Text=r["TenPhuTung"].ToString();partPrice.Text=Convert.ToDecimal(r["DonGia"]).ToString("0.##");partStock.Text=r["SoLuongTon"].ToString();}
 void SavePart(){try{if(string.IsNullOrWhiteSpace(partName.Text))throw new InvalidOperationException("Nhập tên phụ tùng.");svc.Repository.SavePart(partId,partName.Text.Trim(),decimal.Parse(partPrice.Text),int.Parse(partStock.Text));LoadParts();MessageBox.Show("Đã lưu phụ tùng vào kho.");}catch(Exception ex){Error(ex);}}
 void DeletePart(){if(partId is null)return;try{svc.Repository.DeletePart(partId.Value);partId=null;LoadParts();}catch(Exception ex){Error(ex);}}
 void AddLine(){if(partChoice.SelectedItem is not DataRowView r)return;int id=Convert.ToInt32(r["MaPhuTung"]);if(cart.Any(x=>x.PartId==id)){MessageBox.Show("Phụ tùng đã có trong danh sách.");return;}var item=new RepairLine(id,r["TenPhuTung"].ToString()!,Convert.ToInt32(qty.Value),decimal.Parse(labor.Text));cart.Add(item);BindCart();}
 void BindCart(){cartGrid.DataSource=null;var t=new DataTable();t.Columns.Add("MaPhuTung",typeof(int));t.Columns.Add("PhuTung",typeof(string));t.Columns.Add("SoLuong",typeof(int));t.Columns.Add("TienCong",typeof(decimal));foreach(var x in cart)t.Rows.Add(x.PartId,x.PartName,x.Quantity,x.Labor);cartGrid.DataSource=t;}
 void RemoveLine(){if(cartGrid.CurrentRow is null)return;int id=Convert.ToInt32(cartGrid.CurrentRow.Cells[0].Value);cart.RemoveAll(x=>x.PartId==id);BindCart();}
 void CreateRepair(){try{if(repairCar.SelectedValue is null)throw new InvalidOperationException("Chọn xe cần sửa.");int id=svc.Repository.CreateRepair(repairCar.SelectedValue.ToString()!,repairDescription.Text,cart);cart.Clear();BindCart();LoadParts();LoadOrders();MessageBox.Show($"Đã lập phiếu sửa chữa #{id}; kho phụ tùng đã cập nhật.","Hoàn tất");}catch(Exception ex){Error(ex);}}
 void LoadOrders(){var t=svc.Repository.RepairOrders();orders.DataSource=t;reportOrders.DataSource=t.Copy();var r=Controls.Find("report",true).FirstOrDefault() as Label;if(r!=null)r.Text=$"Tổng phiếu: {svc.Repository.Scalar("SELECT COUNT(*) FROM PhieuSuaChua")}     •     Doanh thu đã thanh toán: {svc.Repository.Scalar("SELECT COALESCE(SUM(CASE WHEN TrangThai=N'Đã thanh toán' THEN TongTien ELSE 0 END),0) FROM PhieuSuaChua"):N0} đ";}
 void PaySelected(){if(reportOrders.CurrentRow?.DataBoundItem is not DataRowView r){MessageBox.Show("Chọn phiếu cần thanh toán.");return;}try{svc.Repository.MarkPaid(Convert.ToInt32(r["MaPhieu"]));LoadOrders();MessageBox.Show("Đã chuyển phiếu sang Đã thanh toán.");}catch(Exception ex){Error(ex);}}
 void Error(Exception ex)=>MessageBox.Show(ex.Message,"Có lỗi",MessageBoxButtons.OK,MessageBoxIcon.Warning);
}
